// Normalize and Filter (n8n Code node, run once for all items).
// Turns one inbound message into a fixed shape and decides whether it is customer mail at all.
// Automated mail, the automation's own mail and newsletter traffic are ignored and never answered.
// Each execution of this workflow handles exactly one message, handed over by the poller. The message is
// read from the trigger, because Mailbox Config outputs the configuration only.
const cfg = $('Mailbox Config').first().json;
const m = $('One Email').first().json || {};
// A dry run comes only from the batch test caller. It never calls the model and counts against its own limit.
const dry = m._dry_run && typeof m._dry_run === 'object' ? m._dry_run : null;

const lower = (v) => String(v === undefined || v === null ? '' : v).trim().toLowerCase();
const capBytes = (s, max) => {
  let out = String(s);
  while (Buffer.byteLength(out, 'utf8') > max) out = out.slice(0, Math.max(0, Math.min(out.length - 1, Math.floor(out.length * 0.9))));
  return out;
};
const headerOf = (name) => {
  const h = m.headers || {};
  const key = Object.keys(h).find((k) => k.toLowerCase() === name.toLowerCase());
  const v = key ? h[key] : m[name] !== undefined ? m[name] : m[name.toLowerCase()];
  const line = Array.isArray(v) ? v.join(', ') : String(v === undefined || v === null ? '' : v);
  // The Gmail Trigger stores each header as its whole line ("Auto-Submitted: auto-replied"), so drop the name.
  const prefix = name.toLowerCase() + ':';
  return (line.toLowerCase().startsWith(prefix) ? line.slice(prefix.length) : line).trim();
};
const parseAddress = (v) => {
  if (v && typeof v === 'object') {
    const first = Array.isArray(v.value) ? v.value[0] : v;
    if (first && first.address) return { email: lower(first.address), name: String(first.name || '').trim() };
    if (v.text) v = v.text;
  }
  const s = String(v || '');
  const match = s.match(/<([^<>\s]+@[^<>\s]+)>/) || s.match(/([^\s<>"']+@[^\s<>"']+)/);
  return { email: match ? lower(match[1]) : '', name: s.replace(/<[^>]*>/, '').replace(/"/g, '').trim() };
};

const from = parseAddress(m.from || m.From || headerOf('from'));
const subject = String(m.subject || m.Subject || headerOf('subject') || '').trim();
const text = String(m.text || m.textPlain || m.snippet || '').replace(/\r/g, '').trim();
const messageId = String(m.id || m.messageId || '').trim();
const threadId = String(m.threadId || '').trim();
const labels = Array.isArray(m.labelIds) ? m.labelIds : [];
const replyTo = parseAddress(m.replyTo || headerOf('reply-to'));
// Gmail records its own SPF, DKIM and DMARC verdicts for mail it received. A sender is treated as verified
// only when Gmail says the message really came from the From domain.
const auth = headerOf('authentication-results').toLowerCase();
const senderVerified = /\bdmarc=pass\b/.test(auth) || (/\bdkim=pass\b/.test(auth) && /\bspf=pass\b/.test(auth));

const own = [cfg.mailbox].concat(cfg.own_addresses || []).map(lower);
const reasons = [];
if (!messageId || !threadId) reasons.push('no message id or thread id');
if (!from.email) reasons.push('no sender address');
if (own.includes(from.email)) reasons.push('sent by this mailbox or by the automation');
if (labels.includes('SENT') && !labels.includes('INBOX')) reasons.push('sent mail, not received');
// Also catches the word after a separator, as in forwarding-noreply@google.com.
if (/(^|[._+-])(no-?reply|do-?not-?reply|mailer-daemon|postmaster|bounces?|notifications?|alerts?)[@+._-]/.test(from.email)) reasons.push('automated sender address');
if (/^(auto-generated|auto-replied|auto-notified)/i.test(headerOf('auto-submitted'))) reasons.push('auto-submitted header');
if (/^(bulk|list|junk|auto_reply)/i.test(headerOf('precedence'))) reasons.push('bulk or list precedence');
if (headerOf('list-unsubscribe') || headerOf('list-id')) reasons.push('mailing list or newsletter mail');
if (headerOf('x-autoreply') || headerOf('x-autorespond')) reasons.push('auto-reply header');
if (/^(automatic reply|auto(matic)?[- ]?reply|out of (the )?office|undeliverable|delivery status notification|mail delivery (failed|subsystem))/i.test(subject)) reasons.push('auto-reply or bounce subject');
if ((cfg.system_subject_prefixes || []).some((p) => subject.toLowerCase().startsWith(String(p).toLowerCase()))) reasons.push('subject is one of the automation\'s own emails');

// Launch guards, all set in Mailbox Config. Mail dated before the launch cutoff is never handled.
const sentAt = Date.parse(m.date || headerOf('date'));
const cutoff = cfg.launch_cutoff ? Date.parse(cfg.launch_cutoff) : NaN;
if (!Number.isNaN(cutoff) && (Number.isNaN(sentAt) || sentAt < cutoff)) reasons.push('dated before the launch cutoff, or undated');
// Acceptance window: while this list is not empty, only these senders are handled.
const onlySenders = (cfg.acceptance_senders || []).map(lower);
// A dry run is exempt: it can only come from a manual test workflow and can never reach the model.
if (!dry && onlySenders.length && !onlySenders.includes(from.email)) reasons.push('acceptance window: not a designated test sender');

return [{
  json: {
    action: reasons.length ? 'ignore' : 'handle',
    ignore_reasons: reasons,
    brand: cfg.brand,
    mailbox: lower(cfg.mailbox),
    provider: 'gmail',
    provider_message_id: messageId,
    provider_thread_id: threadId,
    customer_email: from.email,
    customer_name: from.name,
    reply_to_differs: !!replyTo.email && replyTo.email !== from.email,
    // True when the message was written to one of the public addresses and reached this mailbox by
    // forwarding: the original To still names that address, or Gmail's forwarding header does.
    via_public_address: (cfg.public_addresses || []).map(lower).some((a) => a && (
      [m.to, m.cc].flatMap((v) => (v && Array.isArray(v.value) ? v.value : [])).some((x) => lower(x && x.address) === a)
      || headerOf('x-forwarded-for').toLowerCase().includes(a))),
    // Used only by the prepared scope filter and reply path.
    to_addresses: [m.to, m.cc].flatMap((v) => (v && Array.isArray(v.value) ? v.value : [])).map((a) => lower(a && a.address)).filter(Boolean),
    rfc_message_id: /^<[^<>\s]+>$/.test(String(m.messageId || headerOf('message-id')).trim()) ? String(m.messageId || headerOf('message-id')).trim() : '',
    sender_verified: senderVerified,
    subject,
    // The body is capped in bytes, not characters, so one email cannot become one very large model request
    // whatever script it is written in.
    text: capBytes(text, 6000),
    text_truncated: capBytes(text, 6000).length < text.length,
    received_at: new Date().toISOString(),
    // The model call limit is counted in the database (Claim Model Call), so it holds across executions.
    dry_run: !!dry,
    // "{month}" in the configured scope becomes the current month (UTC), which makes the limit a monthly one.
    budget_scope: dry ? 'dryrun:' + String(dry.scope || 'default') : String(cfg.budget_scope || '').replace('{month}', new Date().toISOString().slice(0, 7)),
    budget_max: Math.max(0, Math.floor(Number(dry ? dry.max : cfg.max_model_calls) || 0)),
  },
}];

// Order Lookup (n8n Code node, run once for all items).
// Decides which order facts, if any, may be used for this email. Order details are released only when Gmail
// verified the sender, replies would go back to that same address, and the order's own email matches exactly.
// The database search is a pattern match, so every row is checked again here: a look-alike address gets nothing.
const msg = $('Normalize and Filter').first().json;
const sender = String(msg.customer_email || '').trim().toLowerCase();
const rows = $input.all().map((i) => i.json).filter((o) => o && o.id);
const own = rows.filter((o) => String(o.email || '').trim().toLowerCase() === sender);

let withheld = '';
if (!msg.sender_verified) withheld = 'the sender address could not be verified';
else if (msg.reply_to_differs) withheld = 'replies to this email would go to a different address than the sender';

return [{
  json: {
    withheld_reason: withheld,
    orders: withheld ? [] : own.map((o) => ({
      id: o.id, status: o.status, package: o.package,
      submitted_at: o.submitted_at, plan_generated_at: o.plan_generated_at, delivered_at: o.delivered_at,
    })),
    rows_returned: rows.length,
    rows_matching_sender: own.length,
  },
}];

// Build AI Request (n8n Code node, run once for all items).
// Builds the one model request for an inbound email. The model may use only the approved information and the
// order facts given here. It refuses to build a request until the approved information has been signed off,
// so no model call can happen before then.
const cfg = $('Mailbox Config').first().json;
const msg = $('Normalize and Filter').first().json;
const lookup = $('Order Lookup').first().json || {};
const orders = lookup.orders || [];

const approved = String(cfg.approved_info || '').trim();
if (!approved || /^PASTE APPROVED INFORMATION/i.test(approved)) {
  throw new Error('Approved information has not been signed off and pasted into Mailbox Config. No model call was made.');
}

const orderFacts = lookup.withheld_reason
  ? 'Order details are not available for this email (' + lookup.withheld_reason + '). Do not state anything about any order.'
  : orders.length === 0
  ? 'No order was found for the sender address ' + msg.customer_email + '.'
  : orders.map((o, i) => 'Order ' + (i + 1) + ': package ' + (o.package || 'not recorded')
      + ', status ' + (o.status || 'not recorded')
      + ', submitted ' + (o.submitted_at || 'not recorded')
      + ', plan generated ' + (o.plan_generated_at || 'not yet')
      + ', delivered ' + (o.delivered_at || 'not yet') + '.').join('\n');

const system = [
  'You triage and draft replies to customer email for ' + cfg.brand_name + '. A person reviews what you produce.',
  'Use ONLY the APPROVED INFORMATION and the ORDER FACTS below. If the answer is not there, do not answer: set needs_owner to true.',
  'In the APPROVED INFORMATION, "Elizabeth" is the person you write as. Where it says a matter goes to Elizabeth, that means needs_owner is true.',
  'Never state or imply a delivery date or time. You may repeat a duration only if it appears word for word in the approved information.',
  'Never offer, promise, refuse or discuss refunds, discounts, compensation, guarantees or legal matters. Those go to the owner.',
  'Never invent facts about the order, the plan, the price or the company. Never ask for payment or card details.',
  'Categories: order_status, delivery_timing, how_it_works, pricing, thanks, refund, payment_dispute, cancellation, complaint, legal, privacy, plan_content_question, sensitive, unclear, other.',
  'Only order_status, delivery_timing, how_it_works, pricing and thanks are routine. Everything else needs the owner.',
  'A general question (how it works, pricing, thanks) needs no order: answer it from the approved information alone.',
  'Never mention another person, another email address, or any order that is not listed in the ORDER FACTS.',
  'If you are not confident, or the email asks several things and one is not routine, set needs_owner to true.',
  'Answer with one JSON object and nothing else: {"category": string, "confidence": number from 0 to 1, "needs_owner": boolean, "owner_reason": string, "reply_text": string}.',
  'reply_text is a short reply written as Elizabeth herself, in the first person ("I", "my"), signed on its own last line "Elizabeth Alfond, IdeaToPlan".',
  'Never write about Elizabeth, "she", "the owner" or "the team", and never write "we" or "our". You are writing as her.',
  'Plain text only: no markdown, no asterisks, no bullet points, no headings, no em dashes and no en dashes. Use commas, full stops and short paragraphs.',
  'Begin with "Hi," or "Hi" and the first name, then go straight to the answer. No stock phrases: no "thanks for reaching out", "great question", "feel free to", "happy to help", "sorry for the wait" or similar.',
  'State only what the APPROVED INFORMATION or the ORDER FACTS say, in their words. Add no adjective or assurance of your own (for example "securely", "safe", "instantly"). Never say you can see, have checked or have found anything.',
  'Never promise that anyone will contact the customer, follow up, or do anything "soon" or "shortly".',
  'When needs_owner is true, set reply_text to an empty string. Elizabeth writes those replies herself.',
  '',
  'APPROVED INFORMATION',
  approved,
  '',
  'ORDER FACTS (from the order records, for this sender address only)',
  orderFacts,
].join('\n');

const user = 'From: ' + (msg.customer_name ? String(msg.customer_name).slice(0, 120) + ' ' : '') + '<' + msg.customer_email + '>\n'
  + 'Subject: ' + String(msg.subject).slice(0, 300) + '\n\n' + msg.text + (msg.text_truncated ? '\n[The email was longer and has been cut here.]' : '');

// The size of everything the model is sent. When a limit is configured and the request is larger, no call
// is made and the email goes to the owner, so the cost of one call has a real upper bound.
const requestBytes = Buffer.byteLength(system, 'utf8') + Buffer.byteLength(user, 'utf8');
const maxBytes = Number(cfg.max_request_bytes) > 0 ? Number(cfg.max_request_bytes) : 0;

return [{
  json: {
    request_bytes: requestBytes,
    too_large: maxBytes > 0 && requestBytes > maxBytes,
    request_body: {
      model: cfg.model,
      temperature: 0,
      max_tokens: 700,
      response_format: { type: 'json_object' },
      messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
    },
  },
}];

// Parse AI Answer (n8n Code node, run once for all items).
// Reads the model's JSON answer. Anything unreadable becomes parse_error, which the Decision Gate treats as
// a reason to send the email to the owner.
const r = $input.first().json || {};
if (r.no_model_call) return [{ json: { no_model_call: String(r.no_model_call) } }];
let content = '';
try { content = String(r.choices[0].message.content || ''); } catch (e) { content = ''; }
if (!content) return [{ json: { parse_error: 'the model returned no content' } }];
const start = content.indexOf('{');
const end = content.lastIndexOf('}');
if (start < 0 || end <= start) return [{ json: { parse_error: 'no JSON object in the model answer' } }];
try {
  const o = JSON.parse(content.slice(start, end + 1));
  return [{ json: {
    category: o.category,
    confidence: o.confidence,
    needs_owner: o.needs_owner === true,
    owner_reason: o.owner_reason || '',
    reply_text: o.reply_text || '',
    usage: r.usage || null,
  } }];
} catch (e) {
  return [{ json: { parse_error: 'invalid JSON: ' + e.message } }];
}

// Decision Gate (n8n Code node, run once for all items).
// Code, not the model, decides what happens to an inbound email. The gate fails closed: anything it cannot
// read, anything outside the routine categories, and anything that touches money, disputes or sensitive
// matters goes to the owner. In shadow mode nothing is ever sent to a customer, whatever the outcome.
const cfg = $('Mailbox Config').first().json;
const msg = $('Normalize and Filter').first().json;
const thread = $('Thread State').first().json || {};
const lookup = $('Order Lookup').first().json || {};
const orders = lookup.orders || [];
const ai = $input.first().json || {};

const ROUTINE = ['order_status', 'delivery_timing', 'how_it_works', 'pricing', 'thanks'];
const minConfidence = Number(cfg.min_confidence) > 0 ? Number(cfg.min_confidence) : 0.8;
const maxAutoReplies = Number.isInteger(cfg.max_auto_replies) ? cfg.max_auto_replies : 1;
const approvedMoney = (cfg.approved_money || []).map(String);
const approvedDurations = (cfg.approved_durations || []).map((d) => String(d).toLowerCase());

const reasons = [];
const customerText = (String(msg.subject || '') + '\n' + String(msg.text || '')).toLowerCase();

// 1. Words in the customer's own email that always need the owner, whatever the model said.
const TRIPWIRES = [
  [/\brefund|money back|reimburse|charge ?back/, 'customer mentions a refund or chargeback'],
  [/\bdispute|unauthori[sz]ed|fraud|scam|stolen card|double[- ]charged|charged twice|overcharged/, 'customer mentions a payment problem or dispute'],
  [/\bcancel/, 'customer mentions cancelling'],
  [/\blawyer|attorney|legal action|\bsue\b|lawsuit|small claims|trading standards|consumer protection/, 'customer mentions legal action'],
  [/\bgdpr|delete my data|data protection|right to be forgotten|privacy request|subject access/, 'data or privacy request'],
  [/\bcomplain|unacceptable|disgust|terrible|worst|rip[- ]?off|angry|furious/, 'complaint or strong dissatisfaction'],
  [/\bsuicid|self[- ]harm|kill myself|emergency|bereave|passed away|died\b/, 'sensitive personal situation'],
  [/\bjournalist|press|reporter|media enquiry|interview request/, 'press or media request'],
  [/\b(late|overdue|delayed|still waiting|still have not|still haven'?t|not (yet )?(received|arrived)|taking (so|too) long|past (the )?72)\b/, 'customer says the order is late or has not arrived'],
];
for (const [re, why] of TRIPWIRES) if (re.test(customerText)) reasons.push(why);

// 2. The model's answer must be complete and readable, or the email goes to the owner.
const category = String(ai.category || '').trim().toLowerCase();
const confidence = Number(ai.confidence);
const reply = String(ai.reply_text || '').trim();
if (ai.no_model_call) {
  reasons.push('no model call was made: ' + String(ai.no_model_call).slice(0, 160));
} else {
  if (ai.parse_error) reasons.push('the model answer could not be read: ' + String(ai.parse_error).slice(0, 120));
  if (!category) reasons.push('the model gave no category');
  else if (!ROUTINE.includes(category)) reasons.push('category "' + category + '" is not a routine category');
  if (!(confidence >= 0 && confidence <= 1)) reasons.push('the model gave no usable confidence');
  else if (confidence < minConfidence) reasons.push('confidence ' + confidence + ' is below ' + minConfidence);
  if (ai.needs_owner === true) reasons.push('the model asked for the owner: ' + String(ai.owner_reason || 'no reason given').slice(0, 160));
  if (!reply) reasons.push('the model wrote no reply');
}

// 3. Reply loops and duplicates.
if (Number(thread.auto_reply_count || 0) >= maxAutoReplies) reasons.push('this conversation already had ' + thread.auto_reply_count + ' automated repl' + (thread.auto_reply_count === 1 ? 'y' : 'ies'));
if (thread.prior_status === 'needs_attention') reasons.push('this conversation is already waiting for the owner');

// 4. General questions need no order. An answer about an order needs a verified sender and exactly one order
//    under that sender's own address, so one customer can never be told about another customer's order.
if (['order_status', 'delivery_timing'].includes(category)) {
  if (lookup.withheld_reason) reasons.push('order details were withheld: ' + lookup.withheld_reason);
  else if (orders.length === 0) reasons.push('no order was found for this sender address');
  else if (orders.length > 1) reasons.push(orders.length + ' orders were found for this sender address');
}

// 4b. An order that is past 72 hours and not recorded as delivered is a late order: the owner answers it.
if (orders.length === 1 && !orders[0].delivered_at && orders[0].submitted_at) {
  const hours = (Date.now() - new Date(orders[0].submitted_at).getTime()) / 3600000;
  if (hours > 72) reasons.push('this order was submitted more than 72 hours ago and is not recorded as delivered');
}

// 5. The draft may not state a date, a duration or an amount that is not in the approved information,
//    and may not promise anything.
const draft = reply.toLowerCase();
const MONTHS = 'jan(uary)?|feb(ruary)?|mar(ch)?|apr(il)?|may|jun(e)?|jul(y)?|aug(ust)?|sep(tember)?|oct(ober)?|nov(ember)?|dec(ember)?';
if (new RegExp('\\b\\d{1,2}(st|nd|rd|th)? (' + MONTHS + ')\\b|\\b(' + MONTHS + ') \\d{1,2}\\b|\\b\\d{1,2}[/.-]\\d{1,2}([/.-]\\d{2,4})?\\b').test(draft)) reasons.push('the draft states a calendar date');
if (/\b(today|tonight|tomorrow|this (morning|afternoon|evening|week)|next week|by (monday|tuesday|wednesday|thursday|friday|saturday|sunday)|on (monday|tuesday|wednesday|thursday|friday|saturday|sunday)|shortly|very soon|any minute|right away)\b/.test(draft)) reasons.push('the draft implies a delivery time that is not recorded');
for (const d of draft.match(/\b(?:within|in|under|about|around)?\s*\d+\s*(?:-|to)?\s*\d*\s*(?:minutes?|hours?|days?|weeks?|business days?)\b/g) || []) {
  const norm = d.replace(/\s+/g, ' ').replace(/^(within|in|under|about|around) /, '').trim();
  if (!approvedDurations.includes(norm)) reasons.push('the draft states a duration that is not approved: "' + norm + '"');
}
for (const amt of draft.match(/[$£€]\s?\d[\d,]*(\.\d+)?/g) || []) {
  if (!approvedMoney.includes(amt.replace(/\s/g, ''))) reasons.push('the draft states an amount that is not approved: "' + amt + '"');
}
// "not a guarantee" and "no guarantee" are the approved disclaimers, so they are not treated as an offer.
if (/\b(refund|guarantee|i promise|we promise|compensat|free of charge|discount|credit your)\b/.test(draft.replace(/\b(not a|no) guarantee\b/g, ''))) reasons.push('the draft offers or discusses a refund, guarantee, discount or compensation');

// 5b. Form and voice. A reply is plain text, written by Elizabeth in the first person, with no stock phrases.
if (/[‒–—―]/.test(reply)) reasons.push('the draft contains an em dash or en dash');
if (/\*\*|__|`|^#{1,6}\s|^\s*[-*•]\s|\[[^\]]+\]\([^)]+\)/m.test(reply)) reasons.push('the draft is not plain text (markdown or bullet points)');
const canned = draft.match(/\b(thanks?( you)? (so much )?for (reaching out|getting in touch|your (email|message|interest|patience|question))|great question|good question|i hope this (email|message|helps|finds)|feel free to|(don't|do not) hesitate|happy to help|glad to help|we appreciate|i appreciate your patience|sorry for the (wait|delay|inconvenience)|rest assured)\b/);
if (canned) reasons.push('the draft uses a stock phrase: "' + canned[0] + '"');
// The greeting line and the signature are set aside, so a customer who is also called Elizabeth is not a problem.
const bodyOnly = draft.split('\n').filter((line, i) => !(i === 0 && /^(hi|hello|dear)\b[^.!?]*,?\s*$/.test(line.trim())) && !/^elizabeth alfond, /.test(line.trim())).join('\n');
if (/\belizabeth\b|\bshe\b|\bshe'(ll|s)\b|\bthe owner\b|\bthe team\b|\bour team\b/.test(bodyOnly)) reasons.push('the draft speaks about Elizabeth or a team instead of speaking as Elizabeth');
if (/\b(we|we're|we'll|we've|our)\b/.test(bodyOnly)) reasons.push('the draft says "we" or "our" instead of "I" or "my"');

// 5c. Claims nothing on record supports.
if (/\bi (can |could |do )?see (that )?(your|the|an?) (order|plan|payment|purchase|account|submission)|\bi('ve| have) (found|located|checked|pulled up|reviewed|looked (up|into|at)|received) (your|the) (order|plan|payment|purchase|account|submission|refund|request)|\bi('m| am) looking (at|into) (your|the)/.test(draft)) {
  reasons.push('the draft claims to have seen or checked something that is not on record');
}
const approvedText = String(cfg.approved_info || '').toLowerCase();
const ASSURANCES = ['securely', 'secure', 'safely', 'safe', 'encrypted', 'confidential', 'private', 'privately', 'instantly', 'immediately', 'expert', 'experts', 'certified', 'accurate', 'proven', 'trusted'];
for (const w of ASSURANCES) {
  if (new RegExp('\\b' + w + '\\b').test(draft) && !new RegExp('\\b' + w + '\\b').test(approvedText)) reasons.push('the draft makes an assurance that is not in the approved information: "' + w + '"');
}
if (/\b(be in touch|get back to you|contact you|reach out to you|follow up|hear (back )?from (me|us|her)|respond to you|reply to you|write to you|email you|look into (it|this|that)|flagged (this|it|your)|passing (this|it|your)|pass (this|it|your) (message |email |request )?(on|along))\b/.test(draft)) {
  reasons.push('the draft promises that someone will contact the customer or follow up');
}
if (/\b(soon|asap|as soon as possible|promptly|quickly|in no time|without delay)\b/.test(draft)) reasons.push('the draft implies a delivery time that is not recorded');

// 6. The draft may name no email address but this customer's and the business's own, and no record id.
const allowedAddresses = [String(msg.customer_email || '').toLowerCase(), String(cfg.mailbox || '').toLowerCase()]
  .concat((cfg.public_addresses || []).map((a) => String(a).toLowerCase()));
for (const a of draft.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/g) || []) {
  if (!allowedAddresses.includes(a)) reasons.push('the draft contains an email address that is not this customer\'s: "' + a + '"');
}
if (/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/.test(draft)) reasons.push('the draft contains an internal record id');

const unique = Array.from(new Set(reasons));
const outcome = unique.length ? 'escalate' : 'reply';
const shadow = cfg.shadow !== false; // shadow unless it is switched off explicitly

return [{
  json: {
    outcome,                                  // what the gate decided: reply or escalate
    send_to_customer: outcome === 'reply' && !shadow,
    shadow,
    thread_status: outcome === 'escalate' ? 'needs_attention' : shadow ? 'needs_attention' : 'replied',
    status_reason: outcome === 'escalate'
      ? unique.join('; ')
      : shadow ? 'Shadow mode: a routine reply was drafted and not sent. Review the draft.' : 'Routine reply sent.',
    reasons: unique,
    category: category || 'unknown',
    confidence: confidence >= 0 && confidence <= 1 ? confidence : null,
    reply_text: reply,
    matched_order_id: orders.length === 1 ? orders[0].id : null,
  },
}];

// No Model Call (n8n Code node, run once for all items).
// Reached when the model call limit is used up, or on a dry run. No request is sent to the model. The Decision
// Gate turns this into an escalation, so the owner still hears about the email.
const claim = $('Claim Model Call').first().json || {};
const built = $('Build AI Request').first().json || {};
const why = built.too_large === true
  ? 'the request is larger than the size limit (' + built.request_bytes + ' bytes)'
  : claim.allowed !== true
  ? 'the model call limit is reached (' + claim.calls_used + ' of ' + claim.calls_max + ' used)'
  : 'dry run, the model is not called';
return [{ json: { no_model_call: why } }];

// In Scope (n8n Code node, run once for all items). PREPARED, not in the published handler.
// The mailbox is a working mailbox, so only I2P customer mail is handled. A message is in scope only when
// one of these is true. Anything else is ambiguous and is left in the inbox untouched for manual review:
// no record, no model call, no alert.
//   1. the sender already has an order on record (an existing I2P customer)
//   2. the message belongs to a conversation that is already on record (an existing I2P conversation)
//   3. it was addressed to one of the public I2P addresses (the original I2P destination)
//   4. the subject or body names IdeaToPlan explicitly
// Words like "my order", "business plan" or "starter plan" are NOT enough on their own.
const cfg = $('Mailbox Config').first().json;
const msg = $('Normalize and Filter').first().json;
const lookup = $('Order Lookup').first().json || {};
const knownConversation = $input.all().some((i) => i.json && i.json.id);
const scope = cfg.scope || {};

const out = (inScope, reason) => [{ json: { in_scope: inScope, scope_reason: reason } }];
if (scope.enabled !== true) return out(true, 'scope filter is off');

if (Number(lookup.rows_matching_sender) > 0) return out(true, 'the sender has an order on record');
if (knownConversation) return out(true, 'the conversation is already on record');

const publicAddresses = (cfg.public_addresses || []).map((a) => String(a).toLowerCase());
if (msg.via_public_address === true || (msg.to_addresses || []).some((a) => publicAddresses.includes(a))) return out(true, 'addressed to a public IdeaToPlan address');

// Explicit references only: the name, with or without spaces or hyphens, or the site address.
const text = (String(msg.subject || '') + '\n' + String(msg.text || '')).toLowerCase();
const named = text.match(/\bidea[\s-]?to[\s-]?plan\b|\bideatoplan\.to\b|\bidea2plan\b/);
if (named) return out(true, 'the email names IdeaToPlan ("' + named[0] + '")');

return out(false, 'not an existing customer or conversation, not sent to an IdeaToPlan address, and IdeaToPlan is not named: left in the inbox for manual review');

// Send Plan (n8n Code node, run once for all items). PREPARED, not in the published handler.
// Decides whether the routine reply the gate approved may be sent at all. Everything here is a reason NOT
// to send. In shadow mode the answer is always no.
const cfg = $('Mailbox Config').first().json;
const msg = $('Normalize and Filter').first().json;
const gate = $('Decision Gate').first().json;

if (cfg.shadow !== false || gate.send_to_customer !== true) return [{ json: { send: false, holds: [], wanted: false } }];

const lower = (v) => String(v || '').trim().toLowerCase();
const to = lower(msg.customer_email);
const ours = [cfg.mailbox].concat(cfg.own_addresses || [], cfg.public_addresses || []).map(lower);
const holds = [];
if (cfg.sending_enabled !== true) holds.push('sending is switched off in Mailbox Config');
// Only the categories listed in auto_send_categories are answered automatically. Every other routine
// category, and every category when the list is missing, is held as a draft for the owner.
const autoCategories = Array.isArray(cfg.auto_send_categories) ? cfg.auto_send_categories.map(lower) : [];
if (!autoCategories.includes(lower(gate.category))) holds.push('questions in the category "' + String(gate.category) + '" are held for the owner');
// Mail that arrived through the forwarded public mailbox is held until forwarding has been verified.
if (cfg.hold_forwarded !== false && msg.via_public_address === true) holds.push('this email came through the forwarded public mailbox, and those replies are held for the owner');
// While this list is not empty, a reply may go only to these addresses. Everyone else gets a held draft.
const onlyTo = (cfg.send_only_to || []).map(lower);
if (onlyTo.length && !onlyTo.includes(to)) holds.push('sending is limited to the test address for now');
if (msg.dry_run) holds.push('this is a dry run');
if (!/^[a-z0-9._%+-]+@[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(to)) holds.push('the customer address is not a plain email address');
if (ours.includes(to)) holds.push('the sender is one of the business\'s own addresses, so a reply would go back to the mailbox');
if (!msg.sender_verified) holds.push('the sender address could not be verified');
if (msg.reply_to_differs) holds.push('the email asks for replies at a different address than the sender');
if (!msg.rfc_message_id) holds.push('the email has no Message-ID to thread the reply on');
if (!String(gate.reply_text || '').trim()) holds.push('there is no reply text');

return [{ json: { send: holds.length === 0, holds, wanted: true, to } }];

// Build Reply (n8n Code node, run once for all items). PREPARED, not in the published handler.
// Builds the one reply as a raw message for the Gmail API. The recipient is the customer's own address, set
// here explicitly and never taken from a Reply-To header or from a forwarding mailbox. The reply is threaded
// on the customer's message by In-Reply-To, References and the Gmail thread id.
const msg = $('Normalize and Filter').first().json;
const gate = $('Decision Gate').first().json;
const plan = $('Send Plan').first().json;
if (plan.send !== true) throw new Error('Build Reply was reached without a send plan. Nothing was sent.');

const oneLine = (s) => String(s || '').replace(/[\r\n]+/g, ' ').trim();
const b64 = (s) => Buffer.from(String(s), 'utf8').toString('base64');
const subjectText = oneLine(msg.subject).slice(0, 200);
const subject = /^re:/i.test(subjectText) ? subjectText : 'Re: ' + subjectText;
const body = String(gate.reply_text).replace(/\r?\n/g, '\r\n');

const mime = [
  'To: ' + plan.to,
  'Subject: =?UTF-8?B?' + b64(subject) + '?=',
  'In-Reply-To: ' + msg.rfc_message_id,
  'References: ' + msg.rfc_message_id,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  b64(body).replace(/.{76}/g, '$&\r\n'),
].join('\r\n');

return [{
  json: {
    to: plan.to,
    subject,
    in_reply_to: msg.provider_message_id,
    request_body: { threadId: msg.provider_thread_id, raw: Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '') },
  },
}];

// Send Outcome (n8n Code node, run once for all items). PREPARED, not in the published handler.
// Reads what the Gmail send step returned and sorts it into exactly one of three states:
//   sent      Gmail returned a message id. The reply went out.
//   not_sent  Gmail refused the request outright (a 4xx answer). Nothing went out.
//   unknown   anything else: a timeout, a dropped connection, a 5xx answer, or no answer at all. The reply may
//             or may not have gone out. It is NEVER sent again automatically; the owner checks the Sent folder.
const r = $input.first().json || {};
const built = $('Build Reply').first().json;

const err = r.error;
const text = err ? (typeof err === 'string' ? err : String(err.message || err.description || JSON.stringify(err))) : '';
const codeMatch = text.match(/\b([45]\d\d)\b/);
const status = Number((err && (err.httpCode || err.status || err.statusCode)) || (codeMatch && codeMatch[1]) || 0);

let state;
if (!err && typeof r.id === 'string' && r.id.length > 0) state = 'sent';
else if (err && status >= 400 && status < 500 && status !== 408) state = 'not_sent';
else state = 'unknown';

const base = { state, to: built.to, in_reply_to: built.in_reply_to, gmail_message_id: state === 'sent' ? r.id : null, gmail_thread_id: state === 'sent' ? (r.threadId || null) : null, error: text.slice(0, 300) };
if (state === 'sent') {
  return [{ json: { ...base, event_type: 'reply_sent', thread_status: 'replied', status_reason: 'Routine reply sent to ' + built.to + '.' } }];
}
if (state === 'not_sent') {
  return [{ json: { ...base, event_type: 'send_failed', thread_status: 'needs_attention', status_reason: 'The reply was NOT sent: Gmail refused it (' + (status || 'error') + '). Nothing reached the customer. Answer this one by hand.' } }];
}
return [{ json: { ...base, event_type: 'send_unknown', thread_status: 'needs_attention', status_reason: 'The send did not confirm, so the reply may or may not have reached ' + built.to + '. Check the Sent folder before doing anything. It will not be sent again automatically.' } }];

// Final Status (n8n Code node, run once for all items). PREPARED, not in the published handler.
// Every path ends here: no send wanted, send held, send claim refused, sent, not sent, unknown, and the case
// where the reply went out but writing that down failed. It gives Finish one status and one reason.
const gate = $('Decision Gate').first().json;
const plan = $('Send Plan').first().json;
const ran = (name) => { try { return $(name).isExecuted === true; } catch (e) { return false; } };
const input = $input.first().json || {};

const done = (thread_status, status_reason, extra = {}) => [{ json: { thread_status, status_reason, notify_owner: thread_status !== 'replied', ...extra } }];

if (plan.send !== true) {
  if (plan.wanted && plan.holds.length) return done('needs_attention', 'A routine reply was drafted but not sent: ' + plan.holds.join('; ') + '.');
  return done(gate.thread_status === 'replied' ? 'needs_attention' : gate.thread_status, gate.status_reason);
}

const claim = ran('Claim Send') ? $('Claim Send').first().json || {} : {};
if (claim.claimed !== true) {
  return done('needs_attention', 'A routine reply was drafted but not sent: ' + (claim.reason || 'the send could not be claimed') + '. Nothing was sent by this run.');
}

if (!ran('Send Outcome')) return done('needs_attention', 'The send was claimed but its outcome is not known. Check the Sent folder before doing anything. It will not be sent again automatically.');
const outcome = $('Send Outcome').first().json;
// Record Send Event passes its error here when the outcome could not be written to the history.
if (input.error) {
  const what = outcome.state === 'sent'
    ? 'The reply WAS sent to ' + outcome.to + ' (Gmail message ' + outcome.gmail_message_id + ') but could not be recorded. Do not send it again.'
    : outcome.status_reason + ' That outcome could not be recorded either.';
  return done('needs_attention', what, { record_failed: true });
}
return done(outcome.thread_status, outcome.status_reason);
